package com.lms.entity;import java.time.*;import jakarta.persistence.*;import lombok.*;@Entity @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class EmailNotification{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String toEmail; private String templateName; @Column(columnDefinition="TEXT") private String subject; @Column(columnDefinition="TEXT") private String body; private Long applicationId; private Long userId; private String status; @Column(columnDefinition="TEXT") private String errorMessage; private LocalDateTime sentAt;}